  const otpInput = await page.locator('input[name*="code" i], input[autocomplete="one-time-code"], input[inputmode="numeric"], input[type="tel"]').count();
  return !!(hasOtp && (!hasPass || otpInput > 0));
}
async function piAirbnbFillOtp(page, otp) {
  const otpInput = page.locator('input[name*="code" i], input[autocomplete="one-time-code"], input[inputmode="numeric"], input[type="tel"]').first();
  if (!(await otpInput.count())) throw new Error('OTP input not found on Airbnb page');
  await otpInput.fill(String(otp));
  await page.locator('button:has-text("Continue"), button:has-text("Submit"), button[type="submit"]').first().click().catch(function () {});
