}
async function piAirbnbFinishAndSave(job) {
  const page = job.page;
  const context = job.context;
  await page.goto('https://www.airbnb.com/hosting/reservations', { waitUntil: 'domcontentloaded', timeout: 60000 }).catch(function () {});
  await page.waitForTimeout(2000);
  if (!(await piAirbnbPageLooksLoggedIn(page))) {
    throw new Error('Airbnb login did not reach Hosting. Check credentials/OTP and try again.');
  }
