  job.updatedAt = Date.now();
  job.hint = 'Airbnb connected. You can Pull now.';
  await piLoginCleanup(job, true);
}
async function piAirbnbLoginWorker(job) {
  const email = process.env.AIRBNB_HOST_EMAIL || '';
  const pass = process.env.AIRBNB_HOST_PASSWORD || '';
  let pw;
  try { pw = require('playwright'); } catch (e) {
    job.status = 'error';
    job.error = 'playwright is not installed on this deploy';
    job.updatedAt = Date.now();
    return;
  }
  try {
    job.status = 'starting';
    job.updatedAt = Date.now();
    const browser = await pw.chromium.launch({
      headless: true,
      args: ['--disable-dev-shm-usage', '--no-sandbox']
    });
    job.browser = browser;
    const context = await browser.newContext({
      acceptDownloads: true,
      viewport: { width: 1400, height: 900 },
      userAgent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      locale: 'en-US'
    });
    job.context = context;
    const page = await context.newPage();
    job.page = page;

    await page.goto('https://www.airbnb.com/login', { waitUntil: 'domcontentloaded', timeout: 60000 });
    for (const sel of ['button:has-text("Accept")', 'button:has-text("OK")', '[data-testid="accept-btn"]']) {
      const b = page.locator(sel).first();
      if (await b.count()) await b.click({ timeout: 2000 }).catch(function () {});
    }
    const emailInput = page.locator('#phone-or-email, input[name="email"], input[type="email"], input[autocomplete="username"]').first();
    await emailInput.waitFor({ state: 'visible', timeout: 20000 });
    await emailInput.fill(email);
    await page.locator('button:has-text("Continue"), button[type="submit"]').first().click();
    await page.waitForTimeout(2500);

    if (await piAirbnbNeedsOtp(page)) {
      job.status = 'awaiting_otp';
      job.hint = 'Enter the Airbnb email/SMS code below, then Submit code.';
      job.updatedAt = Date.now();
      return;
    }

    const passInput = page.locator('input[name="password"], input[type="password"]').first();
    if (await passInput.count()) {
      await passInput.fill(pass);
      await page.locator('button:has-text("Log in"), button:has-text("Sign in"), button[type="submit"]').first().click();
      await page.waitForTimeout(4000);
    }

    if (await piAirbnbNeedsOtp(page)) {
      job.status = 'awaiting_otp';
      job.hint = 'Enter the Airbnb email/SMS code below, then Submit code.';
      job.updatedAt = Date.now();
      return;
    }

    const bodyText = await page.locator('body').innerText().catch(function () { return ''; });
    if (/captcha|unusual activity/i.test(bodyText)) {
      throw new Error('Airbnb blocked login (captcha). Retry later, or use Paste session JSON from a normal browser.');
    }

    await piAirbnbFinishAndSave(job);
  } catch (e) {
    job.status = 'error';
    job.error = e.message || String(e);
    job.updatedAt = Date.now();
    await piLoginCleanup(job, true);
  }
}

