async function piAirbnbOtpDeliveryHint(page) {
  const text = (await page.locator('body').innerText().catch(function () { return ''; })).replace(/\s+/g, ' ').trim();
  const email = (text.match(/[\w.+-]+@[\w.-]+\.\w+/) || [])[0];
  const phone = (text.match(/\*{2,}\d{2,4}|\d{2,3}\*{2,}\d{2,4}|ending in\s*\d{2,4}/i) || [])[0];
  if (/email/i.test(text) && !/text message|sms|phone/i.test(text)) {
    return 'Airbnb usually emails this code' + (email ? (' to ' + email) : ' (check the host inbox + spam)') + '. SMS often does not arrive for server logins.';
  }
  if (/text message|sms|phone|mobile/i.test(text)) {
    return 'Airbnb says it sent a text' + (phone ? (' (' + phone + ')') : '') + '. If it does not arrive within a minute, tap Resend as email below.';
  }
  return 'Check the Airbnb host email inbox first (and spam). SMS often does not arrive for this login. Use Resend / Email if needed.';
}
async function piAirbnbPreferEmailDelivery(page) {
  // Choice screens: Email / Text me / Get a code another way
  for (const label of [
    'Email', 'email me', 'Email me a code', 'Send email', 'Get a code by email',
    'Αποστολή email', 'Email αντί'
  ]) {
    const btn = page.locator(`button:has-text("${label}"), a:has-text("${label}"), [role="button"]:has-text("${label}"), label:has-text("${label}")`).first();
    if (await btn.count()) {
      await btn.click({ timeout: 2500 }).catch(function () {});
      await page.waitForTimeout(1500);
      return 'email';
    }
  }
  return null;
}
async function piAirbnbResendCode(page, preferEmail) {
  if (preferEmail) await piAirbnbPreferEmailDelivery(page);
  for (const label of [
    'Resend', 'Send again', 'Didn\'t get a code', 'Get a new code', 'Resend code',
    'Send code again', 'Ξαναστείλε', 'Νέος κωδικός'
  ]) {
    const btn = page.locator(`button:has-text("${label}"), a:has-text("${label}"), [role="button"]:has-text("${label}")`).first();
    if (await btn.count()) {
      await btn.click({ timeout: 2500 }).catch(function () {});
      await page.waitForTimeout(2000);
      return true;
    }
  }
  // More options menu
  for (const label of ['More options', 'Try another method', 'Get a code another way', 'Άλλος τρόπος']) {
    const btn = page.locator(`button:has-text("${label}"), a:has-text("${label}")`).first();
    if (await btn.count()) {
      await btn.click({ timeout: 2500 }).catch(function () {});
      await page.waitForTimeout(1000);
      if (preferEmail) await piAirbnbPreferEmailDelivery(page);
      return true;
    }
  }
  return false;
}
